export const SIDE_SHEET_CSS = "/* 侧边抽屉：覆盖式。**皮肤与 PanelDock 完全共用**（side-panel.css 的 .dshpc-side-surface\n   + 头部 / 拖拽条 / 关闭钮），这里只管「怎么占位」：absolute 贴边、通高、盖在页面上。\n   与分栏的唯一差别：它不挤窄主区（所以没有 sticky、没有占宽、也没有收起）。\n\n   没有收起/耳朵（用户 2026-11-02）：抽屉关就是关。 */\n\n.dshpc-sheet{position:absolute;top:0;bottom:0}\n/* 收起出场（用户 2026-11-02）：宽度收到 0 + 淡出，播完由组件卸载。双类压过 .dshpc-side-surface 的入场动画。 */\n@keyframes dshpc-side-out{to{width:0;opacity:0;border-width:0;overflow:hidden}}\n.dshpc-side-surface.dshpc-sheet--leaving{animation:dshpc-side-out .2s var(--dshpc-ease) forwards;pointer-events:none;}\n/* 面与 Modal 同档（bg-layer-1），PanelDock 仍用页面底：双类压过共用的 .dshpc-side-surface，\n   不碰边框（用户 2026-11-02：只改背景）。 */\n.dshpc-side-surface.dshpc-sheet{background:var(--dshpc-surface-1)}\n/* 贴边那侧描边（与分栏的 border-left 同一套线色），拖拽条永远在**朝内**那一侧。 */\n.dshpc-sheet--left{left:0;border-right:1px solid var(--dshpc-border)}\n.dshpc-sheet--right{right:0;border-left:1px solid var(--dshpc-border)}\n.dshpc-sheet--left .dshpc-dock__resizer{left:auto;right:0}\n/* 内容内距：分栏的 body 把内距交给内容组件（FileBrowser 那类自己带 17px），\n   抽屉是**通用容器**，必须自带 —— 否则文字直接贴面板边（用户 2026-11-02 截图）。\n   左右 14 与头部左内距对齐，上下也留同档呼吸。 */\n.dshpc-sheet__body{padding:14px}\n/* 底栏（可选）：线色与内距对齐面板头部。 */\n.dshpc-sheet__foot{\n  flex:none;display:flex;justify-content:flex-end;gap:8px;\n  padding:10px 14px;border-top:1px solid var(--dshpc-border-faint);\n}\n"
